<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$id=(int)current_user()['id'];$u=find_user($id);$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$bio=trim($_POST['bio']??'');$pic=$u['profile_picture'];
if(!valid_name($name))$errors[]='Name must be 2–100 characters.';if($phone!==''&&!preg_match('/^[0-9+() .-]{7,20}$/',$phone))$errors[]='Invalid phone number.';if(mb_strlen($bio)>500)$errors[]='Bio must be 500 characters or less.';
if(($_POST['remove_picture']??'')==='1'&&$pic){if(is_file(__DIR__.'/'.$pic))@unlink(__DIR__.'/'.$pic);$pic=null;}
if(isset($_FILES['profile_picture'])&&$_FILES['profile_picture']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['profile_picture'];if($f['error']!==UPLOAD_ERR_OK)$errors[]='Upload failed.';elseif($f['size']>MAX_UPLOAD_BYTES)$errors[]='Image must be 2 MB or smaller.';else{$fi=new finfo(FILEINFO_MIME_TYPE);$mime=$fi->file($f['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime])||getimagesize($f['tmp_name'])===false)$errors[]='Only valid JPG, PNG, and WEBP images are allowed.';else{if(!is_dir(UPLOAD_DIR))mkdir(UPLOAD_DIR,0755,true);$fn='user_'.$id.'_'.bin2hex(random_bytes(8)).'.'.$types[$mime];if(move_uploaded_file($f['tmp_name'],UPLOAD_DIR.'/'.$fn)){$pic='uploads/profiles/'.$fn;if($u['profile_picture']&&is_file(__DIR__.'/'.$u['profile_picture']))@unlink(__DIR__.'/'.$u['profile_picture']);}else$errors[]='Could not save image.';}}}
if(!$errors){$s=db()->prepare('UPDATE users SET full_name=?,phone=?,bio=?,profile_picture=? WHERE id=?');$s->execute([$name,$phone?:null,$bio?:null,$pic,$id]);$_SESSION['user']['full_name']=$name;set_flash('success','Profile updated.');redirect('profile.php');}$u['full_name']=$name;$u['phone']=$phone;$u['bio']=$bio;$u['profile_picture']=$pic;}
render_header('My profile');?><section class="heading"><div><p class="eyebrow">ACCOUNT SETTINGS</p><h1>My profile</h1><p class="muted">Update your details and profile photo.</p></div><a class="btn secondary" href="<?=e(BASE_URL)?>/dashboard.php">← Dashboard</a></section><section class="panel form-panel"><?php if($errors):?><div class="alert error"><?php foreach($errors as $x)echo '<p>'.e($x).'</p>';?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="photo-row"><div class="avatar big"><?php if($u['profile_picture']):?><img src="<?=e(BASE_URL.'/'.$u['profile_picture'])?>" alt="Profile photo"><?php else:?><?=e(strtoupper(substr($u['full_name'],0,1)))?><?php endif;?></div><div><b>Profile picture</b><p class="muted">JPG, PNG or WEBP · max 2 MB</p><input type="file" name="profile_picture" accept="image/jpeg,image/png,image/webp"><label class="check"><input type="checkbox" name="remove_picture" value="1"> Remove current picture</label></div></div><div class="two-col"><label>Full name *<input name="full_name" required maxlength="100" value="<?=e($u['full_name'])?>"></label><label>Email<input disabled value="<?=e($u['email'])?>"></label><label>Phone<input name="phone" value="<?=e($u['phone']??'')?>"></label><label>Role<input disabled value="<?=e(ucfirst($u['role']))?>"></label></div><label>Short bio<textarea name="bio" rows="4" maxlength="500"><?=e($u['bio']??'')?></textarea></label><button class="btn">Save profile changes →</button></form></section><?php render_footer();?>
